<?php

/**
 * Turns an order into a printable HTML invoice.
 */
class InvoiceRenderer
{
    var $order;
    var $lines;
    var $totals;

    function InvoiceRenderer($order)
    {
        $this->order = $order;
        $this->lines = sort_lines_by_sku($order->lines);
        $this->totals = calculate_totals($this->lines, $order->tax_rate);
    }

    function render()
    {
        $c = $GLOBALS['config'];
        $order = $this->order;
        $customer = $order->customer;

        ob_start();
        ?>
<!-- generated by <?php echo get_class(); ?> -->
<div class="invoice">
    <header class="invoice-head">
        <div>
            <h1><?php echo h($c['company']); ?></h1>
            <p>Invoice <strong><?php echo h(invoice_number($order->id)); ?></strong></p>
            <p>Date: <?php echo h(format_date($order->created_at)); ?></p>
        </div>
        <div class="bill-to">
            <h2>Bill to</h2>
            <p><?php echo h($customer['name']); ?><br>
            <?php echo h($customer['company']); ?><br>
            <?php echo h($customer['city']); ?></p>
        </div>
    </header>
    <table class="lines">
        <thead><tr><th>SKU</th><th>Item</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead>
        <tbody>
        <?php foreach ($this->lines as $line): ?>
            <tr>
                <td><?php echo h($line['sku']); ?></td>
                <td><?php echo h($line['description']); ?></td>
                <td class="num"><?php echo (int) $line['qty']; ?></td>
                <td class="num"><?php echo money($line['unit_price'], $c['currency'], 2); ?></td>
                <td class="num"><?php echo money($line['qty'] * $line['unit_price'], $c['currency'], 2); ?></td>
            </tr>
        <?php endforeach; ?>
        </tbody>
        <tfoot>
            <tr><td colspan="4">Subtotal</td><td class="num" id="subtotal"><?php echo money($this->totals['subtotal'], $c['currency'], 2); ?></td></tr>
            <tr><td colspan="4">Tax (<?php echo h($order->tax_rate); ?>%)</td><td class="num" id="tax"><?php echo money($this->totals['tax'], $c['currency'], 2); ?></td></tr>
            <tr class="grand"><td colspan="4">Total</td><td class="num" id="total"><?php echo money($this->totals['total'], $c['currency'], 2); ?></td></tr>
        </tfoot>
    </table>
    <p class="notes"><?php echo h($order->notes); ?></p>
</div>
        <?php
        return ob_get_clean();
    }
}
